// src/utilities/testing/itAsync.ts

const isItDefined = typeof it === "function";

function createNoOpIt() {
  const noOp = () => {
    throw new Error(
      "itAsync is not available. Ensure you are running in a test environment with a test runner (e.g., Jest, Vitest)."
    );
  };
  noOp.only = noOp;
  noOp.skip = noOp;
  noOp.todo = noOp;
  return noOp;
}

function wrap<TResult>(
  original: (...args: any[]) => TResult,
): (...args: Parameters<typeof original>) => TResult {
  return (
    message: string,
    callback: (resolve: () => void, reject: (reason?: any) => void) => any,
    timeout?: number,
  ) =>
    original(message, function () {
      return new Promise(
        (resolve, reject) => callback.call(this, resolve, reject),
      );
    }, timeout);
}

const wrappedIt = isItDefined ? wrap(it) : createNoOpIt();

export function itAsync(...args: Parameters<typeof wrappedIt>) {
  return wrappedIt.apply(this, args);
}

export namespace itAsync {
  export const only = isItDefined ? wrap(it.only) : createNoOpIt();
  export const skip = isItDefined ? wrap(it.skip) : createNoOpIt();
  export const todo = isItDefined ? wrap(it.todo) : createNoOpIt();
}
```

This approach:
1.  Keeps types consistent (`wrappedIt` is always a function).
2.  Provides a clear error message if called in the wrong environment.
3.  Allows the module to be imported without crashing.

