#### Option 1: Native JavaScript (No Dependencies)
```typescript
export default class HelperDate {
    // ... existing code ...

    public static getMonthsBetween(start: Date, end: Date): number[] {
        if (start > end) return [];

        const months: number[] = [];
        let current = new Date(start.getFullYear(), start.getMonth(), 1);
        const endDate = new Date(end.getFullYear(), end.getMonth(), 1);

        while (current <= endDate) {
            months.push(current.getMonth());
            current.setMonth(current.getMonth() + 1);
        }
        return months;
    }

    public static getWeeksBetween(start: Date, end: Date): { weekNumber: number, start: Date }[] {
        if (start > end) return [];

        const weeks: { weekNumber: number, start: Date }[] = [];
        let current = new Date(start);
        // Align to start of week (Sunday or Monday, depending on preference)
        const dayOfWeek = current.getDay();
        current.setDate(current.getDate() - dayOfWeek); // Align to Sunday

        const endDate = new Date(end);

        while (current <= endDate) {
            // Calculate ISO week number
            const tempDate = new Date(current);
            tempDate.setHours(0, 0, 0, 0);
            const dayNum = tempDate.getDay() || 7;
            tempDate.setDate(tempDate.getDate() + 3 - (dayNum - 1));
            const yearStart = new Date(tempDate.getFullYear(), 0, 1);
            const weekNo = Math.ceil((((tempDate - yearStart) / 86400000) + 1) / 7);

            weeks.push({
                weekNumber: weekNo,
                start: new Date(current)
            });

            current.setDate(current.getDate() + 7);
        }
        return weeks;
    }
}
```

