        if (start > end) return [];

        const weeks = eachWeekOfInterval({ start, end });
        return weeks.map(week => ({
            weekNumber: parseInt(format(week, 'ww'), 10), // ISO week number
            start: startOfWeek(week)
        }));
    }
}
```

