const e: MyEnum = { A: 1, B: 2 };
// If someone accidentally adds a property:
(e as any).C = 3;

// Object.keys(e) returns ["A", "B", "C"]
// But keyof MyEnum is "A" | "B"
// The function returns ["A", "B", "C"] as Array<"A" | "B">, which is a lie.
```

