import { debounceTime, first } from 'rxjs/operators';

export class App {
  private subjects: { [key: string]: Subject<any[]> } = {};

  public start;
  public h;
  public createElement;

  constructor() {
    // Initialize if needed
  }

  on(name: string, fn: Function, options: any = {}): Subscription {
    // Ensure subject exists
    if (!this.subjects[name]) {
      this.subjects[name] = new Subject<any[]>();
    }

    let observable: Observable<any[]> = this.subjects[name];

    // Apply operators to the observable, not the subject
    if (options.delay) {
      observable = observable.pipe(debounceTime(options.delay));
    }
    if (options.once) {
      observable = observable.pipe(first());
    }

    return observable.subscribe((args) => {
      if (options.debug) console.debug('run: ' + name);
      try {
        fn.apply(this, args);
      } catch (e) {
        console.error('Error in event handler for ' + name, e);
      }
    });
  }

  run(name: string, ...args: any[]): void {
    const subject = this.subjects[name];
    if (!subject) {
      // Original behavior: silently ignore if no subscriber
      return;
    }
    subject.next(args);
  }
