fn valid_triangle_sides() {
    // Test various valid triangles
    assert!(is_a_triangle(3, 4, 5));
    assert!(is_a_triangle(13, 13, 3));
    assert!(is_a_triangle(208, 203, 145));
    assert!(is_a_triangle(244, 360, 159));
}

#[test]
fn invalid_triangle_sides() {
    // Test triangle inequality violations
    assert!(!is_a_triangle(5, 10, 25));
    assert!(!is_a_triangle(5, 25, 10));
    assert!(!is_a_triangle(1, 2, 3)); // Degenerate: 1+2 = 3
    assert!(!is_a_triangle(1, 1, 3)); // 1+1 < 3
}
```

If you intend to test classification (isosceles, acute, obtuse), you need a separate function or assertions that verify those properties, not just `is_a_triangle`.

