### Suggested Refactored Code

```rust
use std::process::Command;
use vagment::logger;

#[derive(Debug)]
struct Machine {
    id: String,
    name: String,
    provider: String,
    state: String,
    directory: String,
}

fn get_vm_info() -> Result<Vec<Machine>, String> {
    let output = Command::new("vagrant")
        .arg("global-status")
        .output()
        .map_err(|e| format!("Failed to execute 'vagrant global-status': {}", e))?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("vagrant global-status failed: {}", stderr));
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut machines = Vec::new();

    for line in stdout.lines() {
        // Skip empty lines and header lines
        if line.trim().is_empty() || line.starts_with("ID") || line.starts_with("NAME") {
            continue;
        }

        let words: Vec<&str> = line.split_whitespace().collect();
        if words.len() != 5 {
            // Skip malformed lines instead of panicking
            continue;
        }

        let machine = Machine {
            id: words[0].to_string(),
            name: words[1].to_string(),
            provider: words[2].to_string(),
            state: words[3].to_string(),
            directory: words[4].to_string(),
        };

        machines.push(machine);
    }

    Ok(machines)
}

fn main() {
    let version = env!("CARGO_PKG_VERSION");
    let command = env::args().nth(1);

    match get_vm_info() {
        Ok(machines) => {
            // Example: Print the machines
            for machine in machines {
                println!("{:?}", machine);
            }
        }
        Err(e) => {
            logger::error(&e);
            std::process::exit(1);
        }
    }

    if command.is_none() {
        logger::error("Please provide a command");
        std::process::exit(1);
    }
}
```

