```typescript
export function getUserId(ctx: Context): string | null {
  const Authorization = ctx.request.get('Authorization');

  // If no Authorization header, user is not authenticated
  if (!Authorization) {
    return null;
  }

  // Extract token, handling potential 'Bearer ' prefix
  let token = Authorization;
  if (token.startsWith('Bearer ')) {
    token = token.slice(7);
  }

  // If token is empty or invalid, return null
  if (!token || token === 'null') {
    return null;
  }

  try {
    const { userId } = jwt.verify(token, process.env.APP_SECRET) as { userId: string };
    return userId;
  } catch (error) {
    // Log error for debugging, but don't crash the request
    console.error('JWT verification failed:', error);
    return null;
  }
}
```

