import _ from 'lodash';

interface IDebouncedProps {
    [key: string]: any;
}

function debouncedHOC<P extends IDebouncedProps>(key: string, wait: number) {
    return function (Comp: React.ComponentType<P>) {
        return function DebouncedComponent(props: P) {
            const callbackRef = useRef(props[key]);
            const debouncedCallbackRef = useRef<_.DebouncedFunc<any>>();

            // Update ref when prop changes
            useEffect(() => {
                callbackRef.current = props[key];
            }, [props[key]]);

            // Create or update debounced function
            useEffect(() => {
                if (debouncedCallbackRef.current) {
                    debouncedCallbackRef.current.cancel();
                }
                debouncedCallbackRef.current = _.debounce((...args: any[]) => {
                    if (callbackRef.current) {
                        callbackRef.current(...args);
                    }
                }, wait);

                return () => {
                    if (debouncedCallbackRef.current) {
