If you must stick to the class component, here’s a corrected version:

```tsx
import React from 'react';
import _ from 'lodash';

interface IDebouncedProps {
    [key: string]: any;
}

function deb(wait: number) {
    return (key: string) =>
        function debounced<P>(Comp: React.ComponentType<P>) {
            class DebouncedComponent extends React.Component<P & IDebouncedProps> {
                debouncedCallback: _.DebouncedFunc<any>;

                constructor(props: P & IDebouncedProps) {
                    super(props);
                    this.debouncedCallback = this.createDebouncedCallback(props[key]);
                }

                createDebouncedCallback(callback: any) {
                    return _.debounce((...args: any[]) => {
                        if (callback) {
                            callback(...args);
                        }
                    }, wait);
                }

                componentDidUpdate(prevProps: P & IDebouncedProps) {
                    if (prevProps[key] !== this.props[key]) {
                        this.debouncedCallback.cancel();
                        this.debouncedCallback = this.createDebouncedCallback(this.props[key]);
                    }
                }

                componentWillUnmount() {
                    this.debouncedCallback.cancel();
                }

                render() {
                    return <Comp {...this.props} [key]: this.debouncedCallback} />;
                }
            }
            return DebouncedComponent;
        };
}

export default deb(600);
```

